<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">    ...</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">mediaCollections, </span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">// Injects &#39;media&#39; and &#39;folders&#39; collections</span></span>
